class KSReplay {
public:
  enum KSReplayStatus { REPLAY_IGNORE, REPLAY_RECORD, REPLAY_PLAYBACK, REPLAY_PAUSED };
  int bch, sfr, brd; uint32 seed; KSReplayStatus status; float playtime, lastPlaytime; bool slomo, fastforward, prepareSlomo, prepareNormal; int slomospeed, ffspeed; uint32 playframe; int lastPlayframe, interpFrame; uint32 mainPOFrame, aiPOFrame; int frameTicks, interpTicks; bool aiSurfer; uint32 numFrames, numMainPOFrames, numAIPOFrames; void *frame, *mainEntityState, *aiEntityState, *mainEntityPO, *aiEntityPO; uint32 maxframes; bool noDraw; char initWaterState[0x50]; void *collisions; int current_collision, num_collisions; bool firstFrame;
  void Play(); void RestoreNextFrame(float);
